<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#E23B2E;
    --blue:#2048A0;
    --yellow:#F4C430;
    --black:#141414;
    --white:#FFFFFF;
    --grey:#EDEAE3;
    --line:12px;
  }
  *{box-sizing:border-box;margin:0;padding:0;}
  html,body{height:100%;}
  body{
    font-family:'Archivo',system-ui,sans-serif;
    background:var(--black);
    color:var(--black);
    -webkit-font-smoothing:antialiased;
  }

  /* The whole page is a Mondrian composition:
     a black grid whose gaps read as thick black lines. */
  .grid{
    display:grid;
    min-height:100vh;
    padding:var(--line);
    gap:var(--line);
    background:var(--black);
    grid-template-columns:5fr 3fr 4fr;
    grid-template-rows:1.25fr 1fr 1fr 1fr 1fr;
    grid-template-areas:
      "title    title    red"
      "title    title    red"
      "painter  blue     red"
      "movement yellow   matter"
      "readmore yellow   matter";
  }
  .cell{
    background:var(--white);
    padding:clamp(18px,2.4vw,34px);
    display:flex;
    flex-direction:column;
    justify-content:center;
    gap:.6em;
  }
  .cell.red{background:var(--red);}
  .cell.blue{background:var(--blue);}
  .cell.yellow{background:var(--yellow);}

  .kicker{
    font-weight:700;
    font-size:clamp(11px,1vw,13px);
    letter-spacing:.22em;
    text-transform:uppercase;
    color:inherit;
  }
  .title{
    font-weight:900;
    font-size:clamp(30px,4.6vw,64px);
    line-height:.98;
    letter-spacing:-.01em;
  }
  .sub{
    font-weight:500;
    font-size:clamp(15px,1.5vw,20px);
  }
  .body{
    font-weight:400;
    font-size:clamp(14px,1.35vw,18px);
    line-height:1.45;
  }
  .big{
    font-weight:900;
    font-size:clamp(20px,2.2vw,30px);
    line-height:1.05;
  }

  /* Title cell holds the composition itself, drawn in CSS. */
  .artwork{
    display:grid;
    background:var(--black);
    gap:6px;
    padding:6px;
    width:min(100%,320px);
    aspect-ratio:1/1;
    margin-bottom:clamp(14px,2vw,26px);
    grid-template-columns:2fr 2fr 3fr;
    grid-template-rows:2fr 2fr 3fr;
    grid-template-areas:
      "a a red"
      "b b red"
      "blue c yellow";
  }
  .artwork span{background:var(--white);}
  .artwork .w-a{grid-area:a;}
  .artwork .w-b{grid-area:b;}
  .artwork .w-c{grid-area:c;}
  .artwork .a-red{background:var(--red);grid-area:red;}
  .artwork .a-blue{background:var(--blue);grid-area:blue;}
  .artwork .a-yellow{background:var(--yellow);grid-area:yellow;}

  .readmore a{
    display:inline-block;
    align-self:flex-start;
    background:var(--black);
    color:var(--white);
    text-decoration:none;
    font-weight:700;
    font-size:clamp(14px,1.3vw,17px);
    padding:.7em 1.1em;
    border:2px solid var(--black);
  }
  .readmore a:hover{background:var(--white);color:var(--black);}

  .meta{
    font-weight:500;
    font-size:clamp(12px,1.1vw,14px);
    letter-spacing:.04em;
  }

  @media (max-width:760px){
    .grid{
      grid-template-columns:1fr;
      grid-template-rows:none;
      grid-template-areas:
        "title"
        "red"
        "painter"
        "blue"
        "movement"
        "yellow"
        "matter"
        "readmore";
    }
    .cell.red,.cell.blue,.cell.yellow{min-height:120px;}
  }
</style>
